package com.chondrimaishrat.elearning.assignment;
import com.chondrimaishrat.elearning.course.Course; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="assignments") public class Assignment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="course_id") private Course course; @Column(nullable=false,length=150) private String title; @Column(nullable=false,length=2000) private String instructions; private LocalDateTime dueAt; protected Assignment(){} public Assignment(Course c,String t,String i,LocalDateTime d){course=c;title=t;instructions=i;dueAt=d;} public Long getId(){return id;} public Course getCourse(){return course;} public String getTitle(){return title;} public String getInstructions(){return instructions;} public LocalDateTime getDueAt(){return dueAt;}}
